UPDATE `exchange_order` SET
pay_way = #{data.payWay}, amount = #{data.amount}, cash_amount = #{data.cashAmount}, up_order_id = #{data.upOrderId}, status = #{data.status}, pay_time = #{data.payTime}, express_company_name = #{data.expressCompanyName}, express_company_code = #{data.expressCompanyCode}, express_no = #{data.expressNo}, express_status = #{data.expressStatus}, refund_amount = #{data.refundAmount}, refund_cash_amount = #{data.refundCashAmount}, refund_time = #{data.refundTime}, refund_remark = #{data.refundRemark}, divide_status = #{data.divideStatus}, divide_amount = #{data.divideAmount}, divide_time = #{data.divideTime}, update_time = #{data.updateTime},
WHERE id = #{data.id}

mapper.select:
SELECT *
FROM `exchange_order`

    AND user_id = #{param.searchField1}
    AND product_id = #{param.searchField2}
    AND `status` = #{param.searchIntStatus}
    AND `express_status` = #{param.searchField3}
    AND `divide_status` = #{param.searchField4}

        AND `order_no` LIKE CONCAT('%', #{param.searchStrField1}, '%')


        AND `product_name` LIKE CONCAT('%', #{param.searchStrField2}, '%')


        AND (phone LIKE CONCAT('%',#{param.keyword},'%') OR nick_name LIKE CONCAT('%',#{param.keyword},'%'))


        AND `create_time` BETWEEN #{param.startTime} AND #{param.endTime}


        AND create_time <= #{param.limitTime}


ORDER BY `id` desc

SELECT count(1) AS order_num, sum(amount) AS total_amount, sum(refund_amount) AS total_refund_amount, sum(num) AS total_num
FROM `exchange_order`

    AND user_id = #{param.searchField1}
    AND product_id = #{param.searchField2}

        AND `status` IN

            #{item}


    AND `status` = #{param.searchIntStatus}
    AND `express_status` = #{param.searchField3}

        AND `order_no` LIKE CONCAT('%', #{param.searchStrField1}, '%')


        AND `product_name` LIKE CONCAT('%', #{param.searchStrField2}, '%')


        AND (phone LIKE CONCAT('%',#{param.keyword},'%') OR nick_name LIKE CONCAT('%',#{param.keyword},'%'))


        AND `create_time` BETWEEN #{param.startTime} AND #{param.endTime}
